// Язык интерфейса Obsidian, если доступен, иначе английский.
// Пока заполнен только en — при отсутствии перевода всегда используется он.
// Язык берётся из настроек плагина; 'auto' — из настроек самого Obsidian.
// На телефоне значение Obsidian не всегда доступно, поэтому и нужен явный выбор.
let CURRENT_LOCALE = 'en';

const LANGUAGE_NAMES = {
  en: 'English',
  de: 'Deutsch',
  fr: 'Français',
  ru: 'Русский',
  ja: '日本語',
  ko: '한국어',
  hi: 'हिन्दी',
  it: 'Italiano',
  es: 'Español',
  pt: 'Português',
  tr: 'Türkçe',
  pl: 'Polski',
  uk: 'Українська',
  vi: 'Tiếng Việt',
  id: 'Bahasa Indonesia',
  /* Два китайских письма в меню легко спутать: у обоих пишем «中文», само
     письмо иероглифами (简体 / 繁體 — так его узнаёт читающий по-китайски)
     и по-английски — для всех остальных. */
  'zh-Hans': '中文（简体）· Chinese Simplified',
  'zh-Hant': '中文（繁體）· Chinese Traditional',
};

/* 8.4.14 (языки): какой китайский. Obsidian пишет 'zh' (упрощённый) и
   'zh-TW' (традиционный); система — zh-CN, zh-SG, zh-TW, zh-HK, zh-MO,
   zh-Hant-… Традиционное письмо: Тайвань, Гонконг, Макао и явное Hant. */
function zhScript(code) {
  const c = String(code || '').toLowerCase();
  return /hant|-tw|-hk|-mo|_tw|_hk|_mo/.test(c) ? 'zh-Hant' : 'zh-Hans';
}

function detectLocale() {
  try {
    if (typeof window !== 'undefined' && window.localStorage) {
      const v = window.localStorage.getItem('language');
      if (v && LOCALES[v]) return v;
      /* 8.4.13 (языки): у Obsidian бывают коды с регионом (pt-BR) — берём
         язык без региона. Китайский так нельзя: у него два письма, их надо
         будет различать по региону (zh-TW → zh-Hant). */
      const base = v ? String(v).slice(0, 2).toLowerCase() : '';
      if (base === 'zh') return zhScript(v);
      if (base && LOCALES[base]) return base;
    }
  } catch (e) { /* хранилище недоступно */ }
  try {
    const nav = (typeof navigator !== 'undefined' && navigator.language) || '';
    const short = nav.slice(0, 2).toLowerCase();
    if (short === 'zh') return zhScript(nav);
    if (LOCALES[short]) return short;
  } catch (e) { /* язык системы недоступен */ }
  return 'en';
}

function setLocale(choice) {
  CURRENT_LOCALE = (choice && choice !== 'auto' && LOCALES[choice])
    ? choice
    : detectLocale();
}

// Узел, который потом вставляется в нужное место вручную
function createDivIn(parent, cls) {
  const el = (parent && parent.doc ? parent.doc : document).createElement('div');
  el.className = cls;
  return el;
}

function t(key, ...args) {
  const table = LOCALES[CURRENT_LOCALE] || LOCALES.en;
  /* 8.5.2: новые строки сначала пишутся только по-русски (просьба автора), а
     остальные языки — потом. До перевода запасной — английский, затем русский. */
  const val = key in table ? table[key] : key in LOCALES.en ? LOCALES.en[key] : LOCALES.ru && LOCALES.ru[key];
  if (val === undefined) {
    // иначе отсутствующая строка молча рисуется пустотой, и поломку не видно
    console.warn('[Heading Rail] missing string:', key);
    return key;
  }
  return withMacKeys(key, typeof val === 'function' ? val(...args) : val);
}

/* 8.4.14: у сочетаний клавиш — то же для macOS в скобках. Сам плагин на Mac
   и так слушает Cmd вместо Ctrl и Option (это Alt); здесь только подпись.
   Ctrl однозначен в любом языке, а «Alt» по-турецки ещё и «низ» — поэтому
   Alt подписывается только в строках про клавиши. */
const MAC_ALT_KEYS = new Set(['optKbMoveBoth', 'optKbMoveAlt']);
function withMacKeys(key, s) {
  if (typeof s !== 'string' || s.indexOf('⌘') >= 0) return s;
  let out = s;
  if (out.indexOf('Ctrl+Z') >= 0) out = out.replace('Ctrl+Z', 'Ctrl+Z (⌘ Cmd+Z)');
  else out = out.replace(/\bCtrl\b/, 'Ctrl (⌘ Cmd)');
  if (MAC_ALT_KEYS.has(key)) out = out.replace(/\bAlt\b/, 'Alt (⌥ Option)');
  return out;
}


