// Настройки, которые могут отличаться на компьютере и на телефоне.
// Ровно эти ключи составляют «профиль» — их можно настроить раздельно
// либо привязать к компьютерным значениям по одному.
/* Base — набор автора. Это и есть значения по умолчанию: плагин ставится
   сразу с ним, отдельно включать ничего не нужно.

   Все цвета здесь пустые, и это осознанно. Пустой цвет означает «взять у
   темы», а тема может быть какой угодно — от почти белой до чёрной. Жёстко
   заданный цвет рано или поздно совпадёт с фоном и станет невидимым, поэтому
   в наборе по умолчанию их нет ни одного. */
/* 8.5.8: размеры, которые можно задавать в процентах окна Obsidian (а не в
   пикселях): от ширины окна ('w') или от высоты ('h'). Процент хранится прямо
   в настройке строкой («13.5%») — так переключение единиц не сбрасывает
   значение, а «назад» возвращает и число, и единицу. Код плагина получает
   уже пиксели: их пересчитывает геттер профиля (pxView) по текущему окну. */
const SIZE_AXES = {
  previewTopGap: 'h', taskShiftExtra: 'w', taskShiftEdge: 'w',
  previewFitEdge: 'w', previewFitNear: 'w', previewOutlineGap: 'w', panelEdgeGap: 'w',
  railEdge: 'w', colGap: 'w', panelGap: 'w', panelWidth: 'w', previewWidth: 'w', previewGap: 'w', menuSideWidth: 'w',
  hoverGrace: 'rail', reactZone: 'w', horizontalRange: 'w', peakLength: 'rest', peakAdd: 'rest', capWidth: 'w',
  lvlW1: 'w', lvlW2: 'w', lvlW3: 'w', lvlW4: 'w', lvlW5: 'w', lvlW6: 'w', searchBtnWidth: 'w', floatResizeLen: 'w', wcGap: 'w',
  mPanelTop: 'h', mPanelBottom: 'h', panelEdgeTop: 'h', panelEdgeBottom: 'h', searchHeight: 'h', floatSize: 'h', floatHeightLen: 'h',
};
/* 8.5.9: и наоборот — настройки, которые по природе в процентах (заметки или
   её окна), можно задать в пикселях: тогда хранится строка «120px», а код
   переводит её в проценты от того, от чего процент и считается (pctFrom). */
const PCT_NATIVE = { railFrom: 'noteH', railTo: 'noteH', scrollToPct: 'viewH', panelMaxShare: 'noteW' };
/* 8.5.11: числа с обязательствами — поле рядом с ползунком принимает только их
   (иначе ползунок и поле спорили: ползунок нечётный, а поле пускало 5,49). */
const ODD_KEYS = new Set(['waveSpan', 'haloSpan']);
const INT_KEYS = new Set(['railDepth', 'outlineDepth', 'waveSpan', 'haloSpan', 'minHeadings']);
const isPct = (v) => typeof v === 'string' && /%\s*$/.test(v);
const isPx = (v) => typeof v === 'string' && /px\s*$/i.test(v);
const isVw = (v) => typeof v === 'string' && /vw\s*$/i.test(v);   // 8.5.11: % ширины окна у «процентных» настроек
/* 8.5.11: проценты бывают двух родов — от окна (w/h) и от начального размера
   самой вещи: длина волны и прибавка — от длины полосок в покое ('rest'),
   запасная зона — от ширины полосок ('rail'). Их пересчитывает сам плагин. */
const winSize = () => {
  let w = 0, h = 0;
  try { w = window.innerWidth; h = window.innerHeight; } catch (e) { /* нет окна */ }
  return { w: w > 0 ? w : 1920, h: h > 0 ? h : 1080 };
};
const pctToPx = (v, axis) => {
  const n = parseFloat(v);
  if (!isFinite(n)) return 0;
  const ws = winSize();
  return Math.round(n / 100 * (axis === 'h' ? ws.h : ws.w) * 10) / 10;
};

