function searchKeywords(key) {
  const toks = String(key || '').replace(/^x-/, '').replace(/([a-z])([A-Z0-9])/g, '$1 $2').replace(/[0-9]+/g, ' ').toLowerCase().split(/[\s_-]+/);
  const out = [];
  const loc = SEARCH_WORDS_I18N[CURRENT_LOCALE] || null;
  for (const tk of toks) {
    if (!tk) continue;
    if (SEARCH_WORDS[tk]) out.push(SEARCH_WORDS[tk]);
    const base = SEARCH_ALIAS[tk] || tk;
    if (loc && loc[base]) out.push(loc[base]);
  }
  return out.join(' ');
}

